method correct_bracketing(brackets: string) returns (result: bool)
    requires brackets != null
    ensures result == (forall i :: 0 <= i < |brackets| ==>
                      (count_opening_brackets(brackets, 0, i) == count_closing_brackets(brackets, 0, i)))

    // Auxiliary function to count opening brackets
    function count_opening_brackets(brackets: string, start: int, end: int) : int
        requires 0 <= start <= end <= |brackets|
        ensures 0 <= count_opening_brackets(brackets, start, end) <= end - start
    {
        var count := 0;
        var i := start;
        while (i < end)
            invariant start <= i <= end
            invariant count == count_opening_brackets(brackets, start, i)
        {
            if brackets[i] == '<' {
                count := count + 1;
            }
            i := i + 1;
        }
        return count;
    }

    // Auxiliary function to count closing brackets
    function count_closing_brackets(brackets: string, start: int, end: int) : int
        requires 0 <= start <= end <= |brackets|
        ensures 0 <= count_closing_brackets(brackets, start, end) <= end - start
    {
        var count := 0;
        var i := start;
        while (i < end)
            invariant start <= i <= end
            invariant count == count_closing_brackets(brackets, start, i)
        {
            if brackets[i] == '>' {
                count := count + 1;
            }
            i := i + 1;
        }
        return count;
    }
```

